"use client";

import { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";

/**
 * The same basemap the app draws, in the browser.
 *
 * Style, glyphs, sprites and tiles are the files committed under
 * `web/public/map`, generated by the same `tools/build_basemap_style.mjs` run
 * that writes the app's copy. That matters more than it sounds: if the public
 * map painted a block a different colour from the one in a volunteer's hand,
 * the data would stop being one dataset and start being two claims.
 *
 * Nothing is fetched from a tile vendor, so there is no key to leak, no quota
 * to exhaust, and no third party watching who reads the map.
 */

// The archive is range-read over HTTP. Registering the protocol is global and
// must happen once, before any map asks for a tile.
let registered = false;
function registerPmtiles() {
  if (registered) return;
  maplibregl.addProtocol("pmtiles", new Protocol().tile);
  registered = true;
}

export type BasemapMapProps = {
  /** [lng, lat] */
  center?: [number, number];
  zoom?: number;
  /** Extra GeoJSON drawn over the basemap, keyed by source id. */
  overlays?: Record<string, GeoJSON.FeatureCollection>;
  className?: string;
  /** Marked up for screen readers; a map alone tells them nothing. */
  label?: string;
};

const TERRELL_HEIGHTS: [number, number] = [-98.456, 29.5025];

export default function BasemapMap({
  center = TERRELL_HEIGHTS,
  zoom = 14.2,
  overlays,
  className,
  label = "Map of the Terrell Heights pilot area",
}: BasemapMapProps) {
  const host = useRef<HTMLDivElement | null>(null);
  const map = useRef<maplibregl.Map | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (!host.current || map.current) return;
    registerPmtiles();

    let cancelled = false;

    // The style is fetched and patched rather than handed over by URL, because
    // MapLibre GL JS rejects a root-relative `sprite`: it must be absolute,
    // and the origin is only known at runtime. Glyphs are templated and
    // resolve relative fine; the sprite is the one that does not, and it fails
    // quietly -- the map still draws, just with no road shields, one-way
    // arrows or town spots, which is easy to miss in review.
    (async () => {
      let style: maplibregl.StyleSpecification;
      try {
        const res = await fetch("/map/style.json");
        if (!res.ok) throw new Error(`style.json ${res.status}`);
        style = await res.json();
      } catch (err) {
        console.error("[basemap]", err);
        if (!cancelled) setFailed(true);
        return;
      }
      if (cancelled || !host.current) return;

      if (typeof style.sprite === "string" && style.sprite.startsWith("/")) {
        style.sprite = `${window.location.origin}${style.sprite}`;
      }

      const m = new maplibregl.Map({
        container: host.current,
        style,
        center,
        zoom,
        // The pilot area is one neighbourhood; letting someone zoom to the
        // whole planet would only show them an empty archive.
        minZoom: 12,
        maxZoom: 18,
        attributionControl: { compact: false },
      });

      m.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");
      m.addControl(new maplibregl.ScaleControl({ unit: "metric" }), "bottom-left");
      m.on("error", (e) => {
        console.error("[basemap]", e.error?.message ?? e);
        setFailed(true);
      });

      map.current = m;
    })();

    return () => {
      cancelled = true;
      map.current?.remove();
      map.current = null;
    };
    // Deliberately once: the camera props are the *initial* camera, and
    // rebuilding the map on every render would discard the user's position.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Overlays are added once the style is up, and replaced in place afterwards
  // so a data refresh does not reload the basemap underneath it.
  useEffect(() => {
    const m = map.current;
    if (!m || !overlays) return;

    const apply = () => {
      for (const [id, data] of Object.entries(overlays)) {
        const existing = m.getSource(id) as maplibregl.GeoJSONSource | undefined;
        if (existing) {
          existing.setData(data);
          continue;
        }
        m.addSource(id, { type: "geojson", data });
        m.addLayer({
          id: `${id}-line`,
          type: "line",
          source: id,
          paint: {
            "line-color": ["coalesce", ["get", "color"], "#2E3440"],
            "line-width": ["interpolate", ["exponential", 1.6], ["zoom"], 13, 1, 18, 6],
            "line-opacity": 0.9,
          },
        });
      }
    };

    if (m.isStyleLoaded()) apply();
    else m.once("load", apply);
  }, [overlays]);

  return (
    <div className={className} style={{ position: "relative" }}>
      <div
        ref={host}
        role="img"
        aria-label={label}
        style={{ position: "absolute", inset: 0, background: "#F3F2EE" }}
      />
      {failed && (
        <p
          style={{
            position: "absolute",
            inset: 0,
            display: "grid",
            placeItems: "center",
            margin: 0,
            padding: "1rem",
            color: "#5A6372",
            textAlign: "center",
          }}
        >
          The map could not be loaded.
        </p>
      )}
    </div>
  );
}
